import sys

class SecureWallet:
    def __init__(self, balance: int):
        if balance < 0:
            print("Invalid Balance")
            sys.exit(0)
        self.balance = balance

    def __add__(self, other):
        if not isinstance(other, SecureWallet):
            return NotImplemented
        return SecureWallet(self.balance + other.balance)

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        balance = int(data)
    except ValueError:
        return
    wallet = SecureWallet(balance)
    total = wallet + wallet
    print(f"Total Balance: {total.balance}")

if __name__ == "__main__":
    main()
